sys_script_client.script:
function onLoad() {
    g_form.setReadOnly('total_cost', true);
    g_form.setReadOnly('approval_tier', true);

    var isNew = g_form.isNewRecord();
    if (isNew) {
        g_form.setValue('quantity', 1);
        // Default "requested for" to the logged-in user (g_user is available on the client without a server call)
        if (!g_form.getValue('requested_for')) {
            g_form.setValue('requested_for', g_user.userID);
        }
    }

    // Fulfilment-only fields are hidden from plain requesters
    if (!g_user.hasRole('x_2228927_equipm_0.fulfiller') && !g_user.hasRole('x_2228927_equipm_0.admin')) {
        g_form.setDisplay('delivery_date', false);
        g_form.setDisplay('delivered_on', false);
    }

}
